3	import "io"
4	
5	// ParseSession aggregates the usage of every agent of a session. It fails
6	// only if the parent transcript cannot be opened; a sub-agent that cannot be
7	// read stays in Agents with no tokens and a FileIssue. It is one full delta
8	// applied to an empty aggregate, the path the live reader takes (D5).
9	func ParseSession(files SessionFiles) (Usage, error) {
10		a := NewAggregate(files.Parent)
11		d := readSession(files, nil, a.Cursor(), timeNow())
12		if d.parentErr != nil {
13			return Usage{}, baseOnly(d.parentErr)
14		}
15		if err := a.Apply(d); err != nil {
16			return Usage{}, err
17		}
18		return a.Usage(), nil
19	}
20	
21	// parseReader folds r into t for agent; name is the file's sanitized base
22	// name and rank its position rank. It reports whether r ends with an
23	// incomplete line. A read error mid-stream keeps what was read and is
24	// recorded as an IssueReadError at the offset consumed; it is not an
25	// unreadable line.
26	func parseReader(t *table, agent, name, rank string, r io.Reader) bool {
27		res, err := scanLines(r, MaxLineBytes, func(line []byte, off int64) {
28			t.addLine(agent, name, pos{rank: rank, off: off}, line)
29		})
30		for _, off := range res.OversizedAt {
31			t.addOversized(name, pos{rank: rank, off: off})
32		}
33		if err != nil {
34			t.addFileIssue(name, pos{rank: rank, off: res.Consumed}, IssueReadError)
35		}
36		return len(res.Tail) > 0
37	}
