331	// Random sessions, random chunking, sub-agents appearing late, metas added
332	// late: the aggregate equals ParseSession after every delta. The seed is
333	// logged; AGENTUSAGE_SEED replays a run.
334	func TestReadDeltaEquivalenceRandom(t *testing.T) {
335		seed := time.Now().UnixNano()
336		if v := os.Getenv("AGENTUSAGE_SEED"); v != "" {
337			n, err := strconv.ParseInt(v, 10, 64)
338			if err != nil {
339				t.Fatal(err)
340			}
341			seed = n
342		}
343		t.Logf("seed %d", seed)
344		for run := 0; run < 200; run++ {
345			rng := rand.New(rand.NewSource(seed + int64(run)))
346			s := newSess(t)
347			type file struct {
348				path    string
349				data    []byte
350				off     int
351				created bool
352				meta    string // written at a random step; "" for none
353				id      string
354			}
355			files := []*file{{path: s.parent(), created: true}}
356			files[0].data = randomLines(rng)
357			s.put(s.parent(), nil)
358			for _, id := range []string{"a1", "b2", "c3", "d4"}[:rng.Intn(5)] {
359				f := &file{path: s.sub(id), data: randomLines(rng), id: id}
360				if rng.Intn(2) == 0 {
361					f.meta = []string{metaUnfinished, metaFinished}[rng.Intn(2)]
362				}
363				files = append(files, f)
364			}
365			a := NewAggregate(s.parent())
366			readApply(t, a)
367			for {
368				var open []*file
369				for _, f := range files {
370					if !f.created || f.off < len(f.data) {
371						open = append(open, f)
372					}
373				}
374				if len(open) == 0 {
375					break
376				}
377				f := open[rng.Intn(len(open))]
378				end := min(f.off+1+rng.Intn(300), len(f.data))
379				if !f.created {
380					s.put(f.path, nil)
381					f.created = true
382				}
383				s.add(f.path, f.data[f.off:end])
384				f.off = end
385				if f.meta != "" && rng.Intn(4) == 0 {
386					s.putMeta(f.id, f.meta, time.Minute)
387					f.meta = ""
388				}
389				readApply(t, a)
390				assertMatchesParse(t, a, s)
391				if t.Failed() {
392					t.Fatalf("run %d (seed %d) diverged", run, seed+int64(run))
393				}
394			}
395			for _, f := range files {
396				if f.meta != "" {
397					s.putMeta(f.id, f.meta, time.Minute)
398				}
399			}
400			readApply(t, a)
401			assertMatchesParse(t, a, s)
402			if t.Failed() {
403				t.Fatalf("run %d (seed %d) diverged at the end", run, seed+int64(run))
404			}
405		}
406	}
