	s.putMeta("b1", metaFinished, 10*time.Second)
	readApply(t, a)
	if *reads != 3 {
		t.Errorf("meta reads = %d after one meta changed, want 3", *reads)
	}
	readApply(t, a)
	if *reads != 3 {
		t.Errorf("meta reads = %d on the pass after, want 3", *reads)
